const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry and time
  const point = ee.Geometry.Point([140.878144, 27.245974]);
  const aoi = point.buffer(2000); // 2 km radius
  const date = '2014-03-30';

  // 2. Try Landsat 8 first
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(aoi)
    .filterDate(date, ee.Date(date).advance(1, 'day'));

  let size = collection.size().getInfo();
  console.log(`Landsat 8 images on ${date}: ${size}`);

  // If no Landsat 8, try Landsat 7
  if (size === 0) {
    collection = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
      .filterBounds(aoi)
      .filterDate(date, ee.Date(date).advance(1, 'day'));
    size = collection.size().getInfo();
    console.log(`Landsat 7 images on ${date}: ${size}`);
  }

  // If still no data, expand date range
  if (size === 0) {
    collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(aoi)
      .filterDate('2014-03-25', '2014-04-05');
    size = collection.size().getInfo();
    console.log(`Landsat 8 images (expanded): ${size}`);
  }

  if (size === 0) {
    console.log('No imagery available for the location and time period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Get the first image and apply cloud mask
  const image = collection.first();

  // Cloud masking for Landsat 8
  const qa = image.select('QA_PIXEL');
  const cloudMask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));

  // 4. Calculate NDWI to identify water
  const green = image.select('SR_B3').multiply(0.0000275).add(-0.2);
  const nir = image.select('SR_B5').multiply(0.0000275).add(-0.2);
  const ndwi = green.subtract(nir).divide(green.add(nir)).updateMask(cloudMask);

  // Land is where NDWI < 0 (not water)
  const land = ndwi.lt(0).selfMask().clip(aoi);

  // Check valid pixels
  const pixelCount = land.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 30,
    maxPixels: 1e9
  }).get('SR_B3').getInfo();

  console.log(`Valid land pixels: ${pixelCount}`);

  if (pixelCount === 0 || pixelCount === null) {
    console.log('No valid land pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Connected components to count islands
  const connected = land.connectedComponents({
    connectedness: ee.Kernel.plus(1),
    maxSize: 256
  });

  const labels = connected.select('labels');

  // Count unique labels (islands)
  const islandCount = labels.reduceRegion({
    reducer: ee.Reducer.countDistinct(),
    geometry: aoi,
    scale: 30,
    maxPixels: 1e9
  }).get('labels').getInfo();

  console.log(`Number of isolated islands: ${islandCount}`);

  if (islandCount === null || islandCount === undefined) {
    console.log('Failed to calculate island count.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 6. Final answer
  if (islandCount === 2) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
